  "matches a range.": { eng: "matches a range.", deu: "trifft einen Bereich.", esp: "coincide con un rango.", fra: "correspond à une plage.", ita: "corrisponde a un intervallo.", jpn: "は範囲を指定します。", kor: "은 범위를 지정합니다.", pol: "pasuje do zakresu.", ptb: "corresponde a um intervalo.", rus: "задаёт диапазон.", spa: "coincide con un rango.", tha: "ระบุช่วง", tur: "bir aralıkla eşleşir.", zhs: "匹配一个范围。", zht: "匹配一個範圍。" },
  "spans patches.": { eng: "spans patches.", deu: "umfasst mehrere Patches.", esp: "abarca varios parches.", fra: "couvre plusieurs patchs.", ita: "copre più patch.", jpn: "は複数のパッチにまたがります。", kor: "은 여러 패치를 아우릅니다.", pol: "obejmuje kilka łatek.", ptb: "abrange várias atualizações.", rus: "охватывает несколько патчей.", spa: "abarca varios parches.", tha: "ครอบคลุมหลายแพตช์", tur: "birden fazla yamayı kapsar.", zhs: "跨越多个版本。", zht: "跨越多個版本。" },
  "Click any run to see the full breakdown.": { eng: "Click any run to see the full breakdown.", deu: "Klicke auf einen Lauf für die vollständige Aufschlüsselung.", esp: "Haz clic en cualquier partida para ver el desglose completo.", fra: "Cliquez sur une partie pour voir le détail complet.", ita: "Clicca una partita per vedere il dettaglio completo.", jpn: "ランをクリックすると詳細が表示されます。", kor: "런을 클릭하면 전체 내역을 볼 수 있습니다.", pol: "Kliknij przejście, aby zobaczyć pełny podział.", ptb: "Clique em qualquer partida para ver o detalhamento completo.", rus: "Нажмите на забег, чтобы увидеть полную разбивку.", spa: "Haz clic en cualquier partida para ver el desglose completo.", tha: "คลิกที่รันใดก็ได้เพื่อดูรายละเอียดทั้งหมด", tur: "Tam dökümü görmek için bir koşuya tıkla.", zhs: "点击任意对局查看完整明细。", zht: "點擊任意對局查看完整明細。" },
  "Try: \"{example}\"": { eng: "Try: \"{example}\"", deu: "Probiere: \"{example}\"", esp: "Prueba: \"{example}\"", fra: "Essayez : \"{example}\"", ita: "Prova: \"{example}\"", jpn: "例: \"{example}\"", kor: "예: \"{example}\"", pol: "Spróbuj: \"{example}\"", ptb: "Tente: \"{example}\"", rus: "Попробуйте: \"{example}\"", spa: "Prueba: \"{example}\"", tha: "ลอง: \"{example}\"", tur: "Dene: \"{example}\"", zhs: "试试：\"{example}\"", zht: "試試：\"{example}\"" },
